import React from "react";

import { Link } from "react-router-dom";
import "../styles/Home.css";

function Home() {
  return (
    <div className="vertical-nav">
      <div className="vertical-navmenu">
      <li><Link to='/new-order'>New Order</Link></li>
      <li><Link to='/'>Announcement group</Link></li>
      <li><Link to='/'>Services</Link></li>
      <li><Link to='/'>Add Funds</Link></li>
      <li><Link to='/'>API</Link></li>
      <li><Link to='/'>Affiliates</Link></li>
      <li><Link to='/'>Child Panel</Link></li>
      <li><Link to='/'>Tickets</Link></li>
      <li><Link to='/'>Mass Order</Link></li>
      <li><Link to='/'>Updates</Link></li>
      </div>
    </div>
      );
}


export default Home;
